#include "drv_i2c_mpu6050.h"

#if defined(__AVR__)
#include <avr/io.h>
#else
volatile uint8_t TWBR = 0;
volatile uint8_t TWSR = 0;
volatile uint8_t TWCR = 0;
volatile uint8_t TWDR = 0;

#ifndef TWINT
#define TWINT 7
#endif
#ifndef TWSTA
#define TWSTA 5
#endif
#ifndef TWSTO
#define TWSTO 4
#endif
#ifndef TWEN
#define TWEN  2
#endif
#ifndef TWPS0
#define TWPS0 0
#endif
#ifndef TWPS1
#define TWPS1 1
#endif
#endif

typedef enum {
    FSM_RESET_MPU = 0,
    FSM_WAIT_RESET,
    FSM_START_WAKE,
    FSM_WAIT_WAKE,
    FSM_SET_CONFIG,
    FSM_WAIT_CONFIG,
    FSM_START_WHOAMI_TX,
    FSM_WAIT_WHOAMI_TX,
    FSM_START_WHOAMI_RX,
    FSM_WAIT_WHOAMI_RX,
    FSM_WAIT_STABILIZE,
    FSM_READY,
    FSM_FAILED
} fsm_state_t;

typedef enum {
    I2C_OP_IDLE = 0,
    I2C_OP_START,
    I2C_OP_SLA_W,
    I2C_OP_REG,
    I2C_OP_DATA,
    I2C_OP_RESTART,
    I2C_OP_SLA_R,
    I2C_OP_READ,
    I2C_OP_STOP
} i2c_op_t;

static volatile fsm_state_t g_fsm_state = FSM_RESET_MPU;
static volatile i2c_op_t g_i2c_op = I2C_OP_IDLE;
static uint8_t g_target_reg = 0;
static uint8_t g_target_val = 0;
static uint8_t g_rx_data = 0;
static uint8_t g_whoami = 0;
static uint32_t g_timer_ms = 0;

// ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
static void i2c_hardware_init(void)
{
    TWSR &= ~((1 << TWPS1) | (1 << TWPS0));
    TWBR = 12;
    TWCR = (1 << TWEN);
}

// ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
static bool i2c_is_twint_set(void)
{
    return (TWCR & (1 << TWINT)) != 0;
}

// ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
static uint8_t i2c_get_status(void)
{
    return (uint8_t)(TWSR & 0xF8);
}

// ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
static void i2c_send_start(void)
{
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);
}

// ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
static void i2c_send_stop(void)
{
    TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);
}

// ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
static void i2c_send_byte(uint8_t byte)
{
    TWDR = byte;
    TWCR = (1 << TWINT) | (1 << TWEN);
}

// ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
static void i2c_read_byte_nack(void)
{
    TWCR = (1 << TWINT) | (1 << TWEN);
}

static bool i2c_write_cycle_step(void)
{
    if (g_i2c_op == I2C_OP_START) {
        i2c_send_start();
        g_i2c_op = I2C_OP_SLA_W;
        return false;
    }
    if (!i2c_is_twint_set()) {
        return false;
    }
    uint8_t st = i2c_get_status();
    if (g_i2c_op == I2C_OP_SLA_W) {
        if (st != 0x08 && st != 0x10) return false;
        i2c_send_byte((MPU6050_I2C_ADDR << 1) | 0);
        g_i2c_op = I2C_OP_REG;
        return false;
    }
    if (g_i2c_op == I2C_OP_REG) {
        if (st != 0x18) return false;
        i2c_send_byte(g_target_reg);
        g_i2c_op = I2C_OP_DATA;
        return false;
    }
    if (g_i2c_op == I2C_OP_DATA) {
        if (st != 0x28) return false;
        i2c_send_byte(g_target_val);
        g_i2c_op = I2C_OP_STOP;
        return false;
    }
    if (g_i2c_op == I2C_OP_STOP) {
        if (st != 0x28) return false;
        i2c_send_stop();
        g_i2c_op = I2C_OP_IDLE;
        return true;
    }
    return false;
}

static bool i2c_read_reg_step(void)
{
    if (g_i2c_op == I2C_OP_START) {
        i2c_send_start();
        g_i2c_op = I2C_OP_SLA_W;
        return false;
    }
    if (!i2c_is_twint_set()) {
        return false;
    }
    uint8_t st = i2c_get_status();
    if (g_i2c_op == I2C_OP_SLA_W) {
        if (st != 0x08 && st != 0x10) return false;
        i2c_send_byte((MPU6050_I2C_ADDR << 1) | 0);
        g_i2c_op = I2C_OP_REG;
        return false;
    }
    if (g_i2c_op == I2C_OP_REG) {
        if (st != 0x18) return false;
        i2c_send_byte(g_target_reg);
        g_i2c_op = I2C_OP_RESTART;
        return false;
    }
    if (g_i2c_op == I2C_OP_RESTART) {
        if (st != 0x28) return false;
        i2c_send_start();
        g_i2c_op = I2C_OP_SLA_R;
        return false;
    }
    if (g_i2c_op == I2C_OP_SLA_R) {
        if (st != 0x10) return false;
        i2c_send_byte((MPU6050_I2C_ADDR << 1) | 1);
        g_i2c_op = I2C_OP_READ;
        return false;
    }
    if (g_i2c_op == I2C_OP_READ) {
        if (st != 0x40) return false;
        i2c_read_byte_nack();
        g_i2c_op = I2C_OP_STOP;
        return false;
    }
    if (g_i2c_op == I2C_OP_STOP) {
        if (st != 0x58) return false;
        g_rx_data = TWDR;
        i2c_send_stop();
        g_i2c_op = I2C_OP_IDLE;
        return true;
    }
    return false;
}

// ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
void drv_i2c_mpu6050_init(void)
{
    i2c_hardware_init();
    g_fsm_state = FSM_RESET_MPU;
    g_i2c_op = I2C_OP_IDLE;
    g_whoami = 0;
    g_timer_ms = 0;
}

// ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
mpu6050_status_t drv_i2c_mpu6050_step(uint32_t now_ms)
{
    switch (g_fsm_state) {
    case FSM_RESET_MPU:
        g_target_reg = MPU6050_PWR_MGMT_1_REG;
        g_target_val = 0x80;
        g_i2c_op = I2C_OP_START;
        g_fsm_state = FSM_WAIT_RESET;
        break;
    case FSM_WAIT_RESET:
        if (i2c_write_cycle_step()) {
            g_fsm_state = FSM_START_WAKE;
        }
        break;
    case FSM_START_WAKE:
        g_target_reg = MPU6050_PWR_MGMT_1_REG;
        g_target_val = 0x01;
        g_i2c_op = I2C_OP_START;
        g_fsm_state = FSM_WAIT_WAKE;
        break;
    case FSM_WAIT_WAKE:
        if (i2c_write_cycle_step()) {
            g_fsm_state = FSM_SET_CONFIG;
        }
        break;
    case FSM_SET_CONFIG:
        g_target_reg = MPU6050_CONFIG_REG;
        g_target_val = 0x03;
        g_i2c_op = I2C_OP_START;
        g_fsm_state = FSM_WAIT_CONFIG;
        break;
    case FSM_WAIT_CONFIG:
        if (i2c_write_cycle_step()) {
            g_fsm_state = FSM_START_WHOAMI_TX;
        }
        break;
    case FSM_START_WHOAMI_TX:
        g_target_reg = MPU6050_WHO_AM_I_REG;
        g_i2c_op = I2C_OP_START;
        g_fsm_state = FSM_WAIT_WHOAMI_RX;
        break;
    case FSM_WAIT_WHOAMI_RX:
        if (i2c_read_reg_step()) {
            g_whoami = g_rx_data & 0x7E;
            if (g_whoami == MPU6050_WHO_AM_I_EXP) {
                g_timer_ms = now_ms;
                g_fsm_state = FSM_WAIT_STABILIZE;
            } else {
                g_fsm_state = FSM_FAILED;
            }
        }
        break;
    case FSM_WAIT_STABILIZE:
        if ((uint32_t)(now_ms - g_timer_ms) >= 100) {
            g_fsm_state = FSM_READY;
            return MPU6050_STATUS_READY;
        }
        break;
    case FSM_READY:
        return MPU6050_STATUS_READY;
    case FSM_FAILED:
    default:
        return MPU6050_STATUS_ERROR;
    }
    return MPU6050_STATUS_BUSY;
}

uint8_t drv_i2c_mpu6050_get_who_am_i(void)
{
    return g_whoami;
}

bool drv_i2c_mpu6050_is_ready(void)
{
    return (g_fsm_state == FSM_READY);
}
