    lib.drv_i2c_mpu6050_step.restype = ctypes.c_int

    lib.drv_i2c_mpu6050_get_who_am_i.argtypes = []
    lib.drv_i2c_mpu6050_get_who_am_i.restype = ctypes.c_uint8

    lib.drv_i2c_mpu6050_is_ready.argtypes = []
    lib.drv_i2c_mpu6050_is_ready.restype = ctypes.c_bool

    # Pointers to registers
    TWBR_p = ctypes.c_uint8.in_dll(lib, "TWBR")
    TWSR_p = ctypes.c_uint8.in_dll(lib, "TWSR")
    TWCR_p = ctypes.c_uint8.in_dll(lib, "TWCR")
    TWDR_p = ctypes.c_uint8.in_dll(lib, "TWDR")

    lib.drv_i2c_mpu6050_init()
    assert TWBR_p.value == 12, "TWBR should be 12 for 400kHz TWI clock"
    assert (TWSR_p.value & 0x03) == 0, "TWPS prescaler should be 0"

    # Simulate non-blocking I2C bus state progression
    now = 0
    max_steps = 1000
    step_count = 0

    while step_count < max_steps:
        st = lib.drv_i2c_mpu6050_step(now)
        if st == 2:  # READY
            break

        # Simulate TWI hardware responses based on control register
        twcr = TWCR_p.value
        if (twcr & (1 << 5)):  # START sent
            TWSR_p.value = 0x08 if (TWSR_p.value == 0) else 0x10
            TWCR_p.value |= (1 << 7)  # TWINT set
        elif (twcr & (1 << 7)):  # Data/Addr sent or Read
            twsr = TWSR_p.value & 0xF8
            if twsr in (0x08, 0x10):
                # SLA+W or SLA+R sent
                TWSR_p.value = 0x40 if (TWDR_p.value & 1) else 0x18
            elif twsr == 0x18:
                # Reg addr sent
                TWSR_p.value = 0x28
            elif twsr == 0x28:
                # Data sent
                TWSR_p.value = 0x28
            elif twsr == 0x40:
                # Read byte requested
                TWDR_p.value = 0x68
                TWSR_p.value = 0x58

        now += 1
        step_count += 1

    assert lib.drv_i2c_mpu6050_is_ready()
    assert lib.drv_i2c_mpu6050_get_who_am_i() == 104
