#include "pid_controller.h"

#define INT32_LIMIT_MAX  ((int32_t)2147483647L)
#define INT32_LIMIT_MIN  ((int32_t)(-2147483647L - 1L))

void pid_controller_init(pid_controller_t *pid,
                         int32_t kp,
                         int32_t ki,
                         int32_t kd,
                         int32_t scale,
                         int32_t out_min,
                         int32_t out_max)
{
    int64_t i_max;
    int64_t i_min;

    if (pid == (void *)0) {
        return;
    }

    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->scale = (scale > 0) ? scale : 1;

    if (out_min > out_max) {
        pid->out_min = out_max;
        pid->out_max = out_min;
    } else {
        pid->out_min = out_min;
        pid->out_max = out_max;
    }

    i_max = (int64_t)pid->out_max * (int64_t)pid->scale;
    i_min = (int64_t)pid->out_min * (int64_t)pid->scale;

    if (i_max > (int64_t)INT32_LIMIT_MAX) {
        pid->integral_max = INT32_LIMIT_MAX;
    } else {
        pid->integral_max = (int32_t)i_max;
    }

    if (i_min < (int64_t)INT32_LIMIT_MIN) {
        pid->integral_min = INT32_LIMIT_MIN;
    } else {
        pid->integral_min = (int32_t)i_min;
    }

    pid->integral = 0;
    pid->prev_error = 0;
}

void pid_controller_reset(pid_controller_t *pid)
{
    if (pid == (void *)0) {
        return;
    }
    pid->integral = 0;
    pid->prev_error = 0;
}

int32_t pid_controller_update(pid_controller_t *pid,
                              int32_t setpoint,
                              int32_t measured)
{
    int32_t error;
    int32_t derivative;
    int64_t p_term;
    int64_t i_term;
    int64_t d_term;
    int64_t total;
    int32_t output;

    if (pid == (void *)0) {
        return 0;
    }

    error = setpoint - measured;
    derivative = error - pid->prev_error;

    p_term = (int64_t)pid->kp * (int64_t)error;
    i_term = (int64_t)pid->ki * (int64_t)error;
    d_term = (int64_t)pid->kd * (int64_t)derivative;

    pid->integral += (int32_t)i_term;
    if (pid->integral > pid->integral_max) {
        pid->integral = pid->integral_max;
    } else if (pid->integral < pid->integral_min) {
        pid->integral = pid->integral_min;
    }

    total = p_term + (int64_t)pid->integral + d_term;
    total = total / (int64_t)pid->scale;

    if (total > (int64_t)pid->out_max) {
        output = pid->out_max;
    } else if (total < (int64_t)pid->out_min) {
        output = pid->out_min;
    } else {
        output = (int32_t)total;
    }

    pid->prev_error = error;

    return output;
}
